script:
(function () {
  'use strict';
  // Inflation-adjusted (real) investment growth.
  //   Each year: balance grows by (1 + r/n)^n; the yearly contribution is added at the start or end.
  //   Real balance after t years = nominal balance ÷ (1 + inflation)^t
  //   Real annual return (Fisher) = (1 + effective nominal rate) ÷ (1 + inflation) − 1
  // Checks (scratchpad tests/inflation-adjusted.test.js): $10,000 at 8% compounded monthly for 20 yrs
  // = $49,268.03 = 10,000 × (1 + 0.08/12)^240, worth $30,066.85 at 2.5% inflation; 7% annual with
  // $1,200 at year end for 20 yrs = $10,000 × 1.07^20 + 1,200 × (1.07^20 − 1)/0.07 = $87,891.44;
  // real rate for 7% annual and 3% inflation = 3.88%; 0% return and 0% inflation = total contributed.
  // Fix vs the old site: inflation is an annual rate and is no longer compounded by the return's
  // compounding frequency in the real-return figure, so the summary rate now matches the table.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function pct(v) {
    if (Math.abs(v) < 0.00005) v = 0;
    return (v * 100).toFixed(2) + '%';
  }

  function project(o) {
    var yearFactor = Math.pow(1 + o.rate / o.n, o.n);
    var balance = o.initial, contributed = o.initial, rows = [];
    for (var y = 1; y <= o.years; y++) {
      var c = o.indexed ? o.annual * Math.pow(1 + o.inflation, y - 1) : o.annual;
      if (o.atStart) balance += c;
      balance *= yearFactor;
      if (!o.atStart) balance += c;
      contributed += c;
      var priceLevel = Math.pow(1 + o.inflation, y);
      rows.push({ year: y, contribution: c, nominal: balance, real: balance / priceLevel, cumInflation: priceLevel - 1 });
    }
    var last = rows[rows.length - 1];
    return { nominal: last.nominal, real: last.real, contributed: contributed, effRate: yearFactor - 1,
             realRate: yearFactor / (1 + o.inflation) - 1, dollar: 1 / (1 + last.cumInflation), rows: rows };
  }

  function update() {
    var o = {
      initial: num('iaInitial'), annual: num('iaAnnual'), rate: num('iaReturn') / 100, inflation: num('iaInflation') / 100,
      years: Math.round(num('iaYears')), n: parseInt(document.getElementById('iaCompound').value, 10),
      atStart: document.getElementById('iaTiming').value === 'start', indexed: document.getElementById('iaIndexed').value === 'yes'
    };
    var error = document.getElementById('iaError');
    var msg = '';
    if ([o.initial, o.annual, o.rate, o.inflation, o.years].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (o.initial < 0 || o.annual < 0) msg = 'Amounts cannot be negative.';
    else if (o.rate < -0.5 || o.rate > 1) msg = 'Enter an annual return from -50% to 100%.';
    else if (o.inflation < -0.1 || o.inflation > 0.5) msg = 'Enter an inflation rate from -10% to 50%.';
    else if (o.years < 1 || o.years > 100) msg = 'Enter 1 to 100 years.';
    else if (o.initial === 0 && o.annual === 0) msg = 'Enter a starting amount or a yearly contribution.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var r = project(o);
    document.getElementById('iaReal').textContent = money.format(r.real);
    document.getElementById('iaNominal').textContent = money.format(r.nominal);
    document.getElementById('iaRealRate').textContent = pct(r.realRate);
    document.getElementById('iaContributed').textContent = money.format(r.contributed);
    document.getElementById('iaGrowth').textContent = money.format(r.nominal - r.contributed);
    document.getElementById('iaNomRate').textContent = pct(r.effRate);
    document.getElementById('iaLost').textContent = money.format(r.nominal - r.real);
    document.getElementById('iaDollar').textContent = money.format(r.dollar);
    document.getElementById('iaSchedule').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.contribution) + '</td><td>' + money.format(row.nominal) +
             '</td><td>' + money.format(row.real) + '</td><td>' + pct(row.cumInflation) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('iaForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
